package edu.klu.foodwaste.web;
import edu.klu.foodwaste.model.*;import edu.klu.foodwaste.repo.*;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.http.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.time.LocalDate;import java.util.*;
@RestController @RequestMapping("/api/waste-records") public class WasteController{
 private final WasteRepository records;private final MealRepository meals;private final UserRepository users;
 public WasteController(WasteRepository r,MealRepository m,UserRepository u){records=r;meals=m;users=u;}
 public record Input(@NotNull Long mealId,@Positive double preparedKg,@PositiveOrZero double consumedKg,@NotNull LocalDate recordDate,String notes){}
 @GetMapping public List<Map<String,Object>> list(@RequestParam(defaultValue="month")String period){LocalDate end=LocalDate.now(),start=switch(period.toLowerCase()){case "day"->end;case "week"->end.minusDays(6);case "all"->LocalDate.of(2000,1,1);default->end.withDayOfMonth(1);};return records.findByRecordDateBetweenOrderByRecordDateDesc(start,end).stream().map(this::dto).toList();}
 @PostMapping public ResponseEntity<?> create(@Valid @RequestBody Input x,Authentication a){if(a==null)return ResponseEntity.status(401).body(Map.of("message","Log in first"));if(!a.getAuthorities().stream().anyMatch(v->Set.of("ROLE_ADMIN","ROLE_KITCHEN").contains(v.getAuthority())))return ResponseEntity.status(403).body(Map.of("message","Kitchen staff or admin only"));if(x.consumedKg()>x.preparedKg())return ResponseEntity.badRequest().body(Map.of("message","Consumed quantity cannot exceed prepared quantity"));Meal meal=meals.findById(x.mealId()).orElse(null);if(meal==null)return ResponseEntity.badRequest().body(Map.of("message","Meal not found"));WasteRecord r=new WasteRecord();r.setMeal(meal);r.setRecordedBy(users.findByEmail(a.getName()).orElseThrow());r.setPreparedKg(x.preparedKg());r.setConsumedKg(x.consumedKg());double waste=Math.max(0,x.preparedKg()-x.consumedKg());r.setWasteKg(waste);r.setWastePercentage(x.preparedKg()==0?0:Math.round(waste/x.preparedKg()*10000.0)/100.0);r.setRecordDate(x.recordDate());r.setNotes(x.notes());return ResponseEntity.status(201).body(dto(records.save(r)));}
 private Map<String,Object> dto(WasteRecord r){Map<String,Object> m=new LinkedHashMap<>();m.put("id",r.getId());m.put("mealId",r.getMeal().getId());m.put("mealName",r.getMeal().getName());m.put("mealType",r.getMeal().getMealType());m.put("preparedKg",r.getPreparedKg());m.put("consumedKg",r.getConsumedKg());m.put("wasteKg",r.getWasteKg());m.put("wastePercentage",r.getWastePercentage());m.put("recordDate",r.getRecordDate());m.put("notes",r.getNotes());m.put("recordedBy",r.getRecordedBy().getName());return m;}
}
